#!/usr/bin/env node
/**
 * Generate the Imperial Elegy custom properties from the single token source.
 *
 *   node scripts/generate-ie-tokens.mjs            # write the stylesheet
 *   node scripts/generate-ie-tokens.mjs --check    # fail if it is out of date
 *
 * The generated file is committed.  `npm run ie:tokens:check` is the CI gate.
 */
import {readFileSync, writeFileSync, mkdirSync} from "node:fs";
import {dirname, resolve} from "node:path";
import {fileURLToPath} from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "..");
const sourcePath = resolve(root, "src/imperialElegy/design/tokens.json");
const outputPath = resolve(
  root,
  "src/imperialElegy/components/styles/00-tokens.generated.css",
);

const tokens = JSON.parse(readFileSync(sourcePath, "utf8"));

/** Every custom property the generator owns, in emission order. */
export function tokenEntries(t) {
  const entries = [];
  const add = (name, value) => entries.push([`--ie-${name}`, value]);

  for (const [key, value] of Object.entries(t.color)) add(key, value);

  for (const [power, values] of Object.entries(t.power)) {
    add(`power-${power}`, values.fill);
    add(`power-${power}-on-dark`, values.onDark);
    add(`power-${power}-on-paper`, values.onPaper);
    if (values.onFill) add(`power-${power}-on-fill`, values.onFill);
    if (values.edge) add(`power-${power}-edge`, values.edge);
  }

  add("font-display", t.font.family.display);
  add("font-ui", t.font.family.ui);
  add("font-data", "var(--ie-font-ui)");

  for (const [key, value] of Object.entries(t.font.size)) {
    add(`font-${key}`, value.size);
    add(`font-${key}-line`, value.line);
    add(`font-${key}-weight`, String(value.weight));
  }

  for (const [key, value] of Object.entries(t.space)) add(`space-${key}`, value);
  for (const [key, value] of Object.entries(t.radius)) add(`radius-${key}`, value);
  for (const [key, value] of Object.entries(t.shadow)) add(`shadow-${key}`, value);

  add("motion-press", t.motion.press);
  add("motion-pop", t.motion.pop);
  add("motion-sheet", t.motion.sheet);
  add("motion-easing-pop", t.motion["easing-pop"]);
  add("motion-easing-sheet", t.motion["easing-sheet"]);

  return entries;
}

export function renderCss(t) {
  const lines = [
    "/* Generated by scripts/generate-ie-tokens.mjs — do not edit by hand.",
    "   Source: src/imperialElegy/design/tokens.json",
    "   Contract: docs/imperial-elegy/VISUAL_SYSTEM.md §4, §5, §6, §8. */",
    ":root {",
  ];
  for (const [name, value] of tokenEntries(t)) lines.push(`  ${name}: ${value};`);
  lines.push("}");
  lines.push("");
  lines.push("/* CJK line-heights come from data-locale, not duplicated selectors. */");
  lines.push('[data-locale="zh_CN"] {');
  for (const [key, value] of Object.entries(t.font.size)) {
    lines.push(`  --ie-font-${key}-line: ${value.lineCjk};`);
  }
  lines.push("}");
  lines.push("");
  return lines.join("\n");
}

const css = renderCss(tokens);

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(outputPath, "utf8");
  } catch {
    console.error(`Missing generated token stylesheet: ${outputPath}`);
    process.exit(1);
  }
  if (current !== css) {
    console.error(
      "Generated Imperial Elegy tokens are out of date.\n" +
        "Run `npm run ie:tokens` and commit the result.",
    );
    process.exit(1);
  }
  console.log("Imperial Elegy tokens are in sync.");
} else {
  mkdirSync(dirname(outputPath), {recursive: true});
  writeFileSync(outputPath, css);
  console.log(`Wrote ${outputPath}`);
}
